package com.chesspulseai.repository; import com.chesspulseai.entity.ChessMove; import java.util.*; import org.springframework.data.jpa.repository.*; public interface ChessMoveRepository extends JpaRepository<ChessMove,Long>{@Query("select m from ChessMove m left join fetch m.analysis where m.game.id=:gameId order by m.moveNumber") List<ChessMove> findDetailedByGameId(Long gameId);}
